import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"2、【坤】 坤下坤上","description":"周易口訣義 - 2、【坤】 坤下坤上","frontmatter":{"title":"2、【坤】 坤下坤上","description":"周易口訣義 - 2、【坤】 坤下坤上"},"headers":[],"relativePath":"classics/koujueyi/004.md","filePath":"classics/koujueyi/004.md"}'),r={name:"classics/koujueyi/004.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_2、【坤】-坤下坤上" tabindex="-1">2、【坤】 坤下坤上 <a class="header-anchor" href="#_2、【坤】-坤下坤上" aria-label="Permalink to “2、【坤】 坤下坤上”">​</a></h1><p>彖曰：至哉坤元，萬物資生，乃順承天。坤厚載物，德合無疆。含弘光大，品物咸亨。牝馬地類，行地無疆，柔順利貞。君子攸行，先迷失道，後順得常。西南得朋，乃與類行。東北喪朋，乃終有慶。安貞之吉，應地無疆。</p><p>象曰：地勢坤，君子以厚德載物。初六，履霜，堅冰至。</p><p>象曰：「履霜堅冰」，陰始凝也，馴致其道，至堅冰也。</p><p>六二，直方大，不習無不利。</p><p>象曰：六二之動，直以方也。「不習無不利」，地道光也。六三，含章可貞，或從王事，無成有終。</p><p>象曰：「含章可貞」，以時發也；「或從王事」，知光大也。六四，括囊，無咎無譽。</p><p>象曰：「括囊無咎」，慎不害也。六五，黃裳元吉。</p><p>象曰：「黃裳元吉」，文在中也。</p><p>上六，龍戰於野，其血玄黃。</p><p>象曰：「龍戰於野」，其道窮也。用六，利永貞。</p><p>象曰：用六「永貞」，以大終也。</p><p>解讀</p><p>坤，元亨，利牝馬之貞。坤，地也，順也，地之為體，能生始萬物，各得亨通，故有「元亨」也。「利牝馬之貞」者，地體必以柔順而為其正，故借牝馬而為其貞，牝馬是柔順之物，所以將馬為喻，馬行地能窮其邊疆，是明地有廣之德，故先儒雲：「在天為龍，在地為馬。」「君子有攸往」者，明君子但以柔順為德，又復行其貞正，故利有所往也。「先迷，後得主利」者，夫陰之為道，不可首倡居先，若在陽氣之先，則不能發生滋育，必待陽而為首，所以「後得主利」也。猶如臣子處君之朝，順事主終，在家為迷，得主為利也。「西南得朋」者，西南坤位，是陰也，今以陰就陰，是「得朋」也。「東北喪朋，安貞吉」者，東北艮位，為陽也，西南陰類，往雖得朋，必無所利，若能喪失朋而就陽，則獲安靜貞正之吉。以人事明之，猶人臣離其黨，入君之朝，女子舍其家，入夫之室是也。</p><p>象曰：「地勢坤，君子以厚德載物」者，天圓地方，是形不順也，其勢承順天道之常，故曰「地勢坤」也。君子當須以容厚為德，包載萬物，象地之道廣育也。</p><p>「初六，履霜，堅冰至」者，初六陰氣之微，要假積漸以成其功，故引「履霜」以為其喻。且五月一陰爻始生，九月五陰始為霜降，至於十一月，乃至堅冰。此明禍福之由，積久乃顯，所以防萌杜漸，慎終於始。故文言云：「臣弒其君，子弒其父，猶辨之不早辨也。」</p><p>「六二，直方、大，不習無不利」，六二居中得位，盡地之美，故有三德：「直、方、大」，生物不邪，「直」也；地體安厚，「方」也；無所不載，「大」也。既有斯德，盡地之善，故不假積習而「無不利」。施之於人，為臣忠，為子孝，與朋友信故也。</p><p>「六三含章可貞，或從王事，無成有終」者，六三既居上位，有造為陽之事者，含章美之德，待時而發，可以得貞之吉。既居臣體，不可先倡，「或從王事」者，言其不敢自專也；「無成有終」者，不敢居事之先，主成於物，惟順君命而成其終。</p><p>「六四括囊，無咎無譽」者，括，結也；囊，所以盛物，喻人心藏智也。既是陰位，不可顯發，亦猶不遇其時，閉而不用也，故曰「括囊」也。戒慎自守，不與物忤，故曰「無咎」也。德既不施，無聲譽之美，故曰「無譽」也。</p><p>六五「黃裳，元吉」者，五是貴位，六以陰居之，是臣道極貴者也。黃是中之色也，裳是下之飾也。上衣比君，下裳法臣，六五既是臣體，不可比衣，故云「黃裳」，以表臣道黃中之美也。以文德居中，盡臣之善，故獲「大吉」也。</p><p>「上六：龍戰於野，其血玄黃」者，上六陰極似陽，故稱「龍」也；陰既強盛，則侵於陽，故與陽氣之龍交戰也。戰於卦外，故曰「野」也。陰陽俱傷，故有玄黃之色也。陽色玄，陰色黃也。「用六，利永貞」者，用總此六爻之義也。坤體柔順，不可用之剛暴，故須永長貞正，則能廣大而終也。乾吉在「無首」，坤利在「永貞」。</p>',21)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
